#include <iostream>

int main()
{
    double a{};
    char op{};
    double b{};
    std::cin >> a >> op >> b;

    switch (op)
    {
    case '+':
        std::cout << a + b << '\n';
        break;
    case '-':
        std::cout << a - b << '\n';
        break;
    case '*':
        std::cout << a * b << '\n';
        break;
    case '/':
        if (b == 0)
        {
            std::cout << "Cannot divide by zero\n";
        }
        else
        {
            std::cout << a / b << '\n';
        }
        break;
    default:
        std::cout << "Unknown operator\n";
        break;
    }
    return 0;
}
